using System;
using Sandbox;

namespace Survival;

/// <summary>
/// One-handed sword presentation on the sword build of the human graph
/// (<c>models/player/human_male_sword.vmdl</c> → <c>human_sword.vanmgrph</c>, generated by
/// <c>Tools/make_human_sword_assets.py</c>; clips authored in <c>Blender/scripts/create_sword_anims.py</c>).
/// Two phases, no animated windup: the graph's <c>sword_pose</c> selector holds the sword on the
/// shoulder of the side the player is aiming from (rest R / rest L), a click switches it to the matching
/// COCKED pose at once (the elbow cocks back and hangs through the windup), and when the host's damage
/// window opens <c>b_attack</c> plays the strike clip picked by <c>sword_attack</c> — every strike clip starts
/// on its cocked frame and sweeps the path over the class active time, then settles back to rest. A new
/// click sets <c>b_sword_interrupt</c> (0.12 s cut into the next cocked pose) and a raised guard sets
/// <c>b_sword_guard</c>, which both cuts a settling strike and switches the graph's guard selector to the
/// <c>Sword_Block</c> pose (blade level in front of the head) in 0.05 s — the guard is not a <c>sword_pose</c> value,
/// so the rest / cock / shoulder-swap blends keep their own 0.12 s. Remote peers get rest side (Sync), cocked pose and
/// strike (host swing broadcast) on the same timeline.
/// </summary>
public sealed partial class PlayerAnimation
{
	[Property, Group( "Animation" ), Title( "Strike clip length (s)" ), Description( "Wall-clock length of the authored strike clips (Sword_Attack_*: cocked → 0.2 s damage swoop → follow-through held → settle → rest, create_sword_anims.py STRIKE_END). A follow-up click or a block interrupts the follow-through." ), Range( 0.2f, 1.5f ), Step( 0.01f )]
	public float MeleeStrikeClipSeconds { get; set; } = 0.64f;

	/// <summary>Graph <c>sword_pose</c> values: children of the pose selector in holdtype_melee_sword.vsubgrph.</summary>
	static class SwordPose
	{
		public const int CockedL = 0;
		public const int RestL = 1;
		public const int RestR = 2;
		public const int CockedR = 3;
		public const int CockedOver = 4;
		public const int CockedStab = 5;
		public const int SwapMid = 6;
		public const int RestUp = 7;
	}

	/// <summary>Rest stances (<see cref="NetworkedSwordRestSide"/>): sword on the right shoulder, on the left, or raised (aiming up).</summary>
	const byte StanceRight = 0, StanceLeft = 1, StanceUp = 2;

	static int RestPoseFor( byte stance ) => stance switch
	{
		StanceLeft => SwordPose.RestL,
		StanceUp => SwordPose.RestUp,
		_ => SwordPose.RestR
	};

	[Property, Group( "Animation" ), Title( "Shoulder swap hold (s)" ), Description( "How long the sword stays up in front (Sword_Swap_Mid) when changing shoulders before it lays onto the other one. The graph cross-fades 0.12 s into and out of it." ), Range( 0.05f, 0.4f ), Step( 0.01f )]
	public float SwordSwapMidSeconds { get; set; } = 0.14f;

	/// <summary>Shoulder the sword is shown on right now (0 right, 1 left) — changes only through the swap pose or a strike that ends on the other side.</summary>
	byte _shownRestSide;
	bool _swapInProgress;
	byte _swapTarget;
	double _swapMidUntil;
	/// <summary>A press whose wind-up is on the other side of the face from the shown shoulder goes up in front first.</summary>
	bool _cockViaMid;
	double _cockMidUntil;

	/// <summary>Graph <c>sword_attack</c> values: children of the strike selector.</summary>
	static class SwordAttack
	{
		public const int R = 0;
		public const int L = 1;
		public const int Over = 2;
		public const int Stab = 3;
	}

	/// <summary>Rest stance the owner is aiming from: 0 = right shoulder, 1 = left shoulder, 2 = raised (aiming up). Host-synced for remotes.</summary>
	[Sync( SyncFlags.FromHost )]
	public byte NetworkedSwordRestSide { get; set; }

	/// <summary>The cocked pose is applied and the strike has not fired yet (click → windup).</summary>
	bool _swordCocked;
	/// <summary>A strike is scheduled (release / host start) — the swing is committed.</summary>
	bool _swordStrikeScheduled;
	bool _swordStrikeStarted;
	double _swordStrikeAtSandbox;
	byte _swordAttackType;
	bool _appliedSwordInterrupt;
	bool _appliedSwordGuard;
	bool _ownerSkipNextRemoteSwingApply;
	int _appliedSwordPose = -1;
	int _appliedSwordAttack = -1;
	byte _ownerRestSideSent = 255;

	/// <summary>Cocked pose on and no strike scheduled yet.</summary>
	public bool IsMeleeSwingSnapActive => _swordCocked && !_swordStrikeScheduled;

	/// <summary>
	/// Single gate for "a committed strike is playing": from the strike being scheduled through the clip's
	/// return to rest. Purely time-bounded so it can never latch busy forever. Both the next attack and the
	/// arc overlay are bound to this. The press cocked pose is deliberately excluded — the attack being
	/// aimed must still be allowed to fire.
	/// </summary>
	public bool IsMeleeSwingAnimBusy => GetMeleeAttackAnimBusyRemainingSeconds() > 0.01f;

	/// <summary>The strike clip (the damage swoop and its settle) is playing - not the cocked windup / held heavy.</summary>
	public bool IsMeleeStrikePresenting => _swordStrikeStarted && IsMeleeSwingAnimBusy;

	/// <summary>True while a cocked pose or a committed strike owns the sword arm.</summary>
	public bool HasActiveMeleeSwingPresentation => _swordCocked || IsMeleeSwingAnimBusy;

	static int CockedPoseFor( byte attackType ) => attackType switch
	{
		MeleeAttackTypes.Left => SwordPose.CockedL,
		MeleeAttackTypes.Forward => SwordPose.CockedOver,
		MeleeAttackTypes.Stab => SwordPose.CockedStab,
		_ => SwordPose.CockedR
	};

	static int StrikeFor( byte attackType ) => attackType switch
	{
		MeleeAttackTypes.Left => SwordAttack.L,
		MeleeAttackTypes.Forward => SwordAttack.Over,
		MeleeAttackTypes.Stab => SwordAttack.Stab,
		_ => SwordAttack.R
	};

	/// <summary>Left attacks rest on the left shoulder, aiming up raises the sword (blade tipped back, ready to slam down), everything else rests on the right.</summary>
	static byte RestSideFor( byte attackType ) => attackType switch
	{
		MeleeAttackTypes.Left => StanceLeft,
		MeleeAttackTypes.Forward => StanceUp,
		_ => StanceRight
	};

	/// <summary>
	/// Clip family for an attack: a thrust weapon (spear, class <c>forwardAttackIsThrust</c>) stabs on every
	/// direction - its side attacks are angled stabs on the path, so they cock and strike with the stab clips.
	/// </summary>
	byte PresentedAttackType( byte attackType ) =>
		ResolveCombat() is { IsValid: true } combat && combat.GetMeleeWeaponTimings().ForwardAttackIsThrust
			? MeleeAttackTypes.Stab
			: attackType;

	float StrikePresentationSeconds() => Math.Max( 0.2f, MeleeStrikeClipSeconds );

	/// <summary>Owner click: cocked pose now (a strike still settling is cut short), held until the strike fires.</summary>
	public void BeginMeleeSwingSnap( byte attackType )
	{
		if ( !PlayMeleeSwingAnimation || !GameObject.IsValid() )
			return;

		attackType = PresentedAttackType( attackType );
		if ( _swordCocked && !_swordStrikeScheduled )
		{
			_swordAttackType = attackType;
			return;
		}

		_swordCocked = true;
		_swordStrikeScheduled = false;
		_swordStrikeStarted = false;
		_swordStrikeAtSandbox = double.MaxValue;
		_swordAttackType = attackType;
		_meleeAttackAnimBusyUntilSandbox = 0;
		ApplyHoldPose( HoldPose.MeleeTwoHand );

		Components.Get<PlayerCombat>()?.LogMeleeAnimStart(
			"graph cocked pose (held)",
			$"type={MeleeAttackTypes.Label( attackType )} sword_pose={CockedPoseFor( attackType )}" );
	}

	/// <summary>
	/// Owner click: commit the strike. The cocked pose holds for the predicted windup, then the strike clip
	/// fires. The host re-schedules with its authoritative windup when it accepts the swing.
	/// </summary>
	public void ReleaseMeleeSwingSnap( byte attackType, float windupRemainingSeconds )
	{
		if ( !PlayMeleeSwingAnimation || !GameObject.IsValid() )
			return;

		_ownerSkipNextRemoteSwingApply = true;
		ScheduleMeleeStrike( attackType, windupRemainingSeconds, "owner click" );
	}

	/// <summary>Owner heavy: the button came up — move the pending strike there (never earlier than the heavy windup).</summary>
	internal void RescheduleOwnerStrike( double strikeAtSandbox )
	{
		if ( !_swordCocked || !_swordStrikeScheduled || _swordStrikeStarted )
			return;

		_swordStrikeAtSandbox = strikeAtSandbox;
		_meleeAttackAnimBusyUntilSandbox = strikeAtSandbox + StrikePresentationSeconds();
	}

	/// <summary>Drop the cocked pose / pending strike (block, shove, hit reaction).</summary>
	public void CancelMeleeSwingSnap()
	{
		if ( !_swordCocked && !_swordStrikeScheduled )
			return;

		EndMeleeSwing( "cancel" );
	}

	/// <summary>
	/// Host / local swing commit with the authoritative remaining windup. Cocks first when nothing is on
	/// screen (remote peers, host pawn without a press), then schedules the strike.
	/// </summary>
	/// <summary>
	/// <see cref="PlayMeleeSwingAttack"/> windup value meaning "cock now, strike when the host's strike cue arrives".
	/// Everyone but the pawn's own driver presents swings this way, so a light that is held into a heavy never
	/// shows a strike at the light time.
	/// </summary>
	public const float StrikeOnCue = -1f;

	/// <summary>How long a cocked pose waits for a strike cue that never comes (lost packet) before it lets go.</summary>
	const float StrikeCueTimeoutSeconds = 2f;

	/// <param name="windupRemainingSeconds">Seconds until the strike on this machine, or <see cref="StrikeOnCue"/>.</param>
	/// <param name="applyLocally">False: only broadcast (the host's own driven pawn already predicted the swing).</param>
	public void PlayMeleeSwingAttack( byte attackType, bool broadcastFromHost, float windupRemainingSeconds, bool applyLocally = true )
	{
		if ( !PlayMeleeSwingAnimation || !GameObject.IsValid() )
			return;

		if ( applyLocally )
			ScheduleMeleeStrike( attackType, windupRemainingSeconds, windupRemainingSeconds < 0f ? "host swing start (strike on cue)" : "host strike" );

		if ( !broadcastFromHost )
			return;

		// Remote peers never get the light windup: a swing start cocks and holds, the host's cue (0) strikes.
		windupRemainingSeconds = windupRemainingSeconds > 0f ? StrikeOnCue : windupRemainingSeconds;

		if ( GameObject.Network is not { Active: true } || !Networking.IsHost )
			return;

		NetworkedHoldPose = (byte)HoldPose.MeleeTwoHand;
		NetworkedSwingAttackType = attackType;
		NetworkedSwingWindupRemainingSeconds = windupRemainingSeconds;
		NetworkedSwordRestSide = RestSideFor( attackType );
		NetworkedSwingCounter++;

		_deferredSwingAnimType = attackType;
		_deferredSwingAnimWindupRemaining = windupRemainingSeconds;
		_deferSwingAnimBroadcast = true;
	}

	void ScheduleMeleeStrike( byte attackType, float windupRemainingSeconds, string source )
	{
		ApplyHoldPose( HoldPose.MeleeTwoHand );
		attackType = PresentedAttackType( attackType );

		// A strike that already fired is the PREVIOUS swing still settling: this is the next swing (a
		// follow-up click fires the moment the damage swoop ends), so it re-cocks and schedules fresh.
		_swordStrikeStarted = false;
		var onCue = windupRemainingSeconds < 0f;
		var remaining = Math.Max( 0f, windupRemainingSeconds );
		_swordCocked = true;
		_swordAttackType = attackType;
		_swordStrikeScheduled = true;
		_swordStrikeAtSandbox = onCue ? double.MaxValue : Time.NowDouble + remaining;
		_meleeAttackAnimBusyUntilSandbox = onCue
			? Time.NowDouble + StrikeCueTimeoutSeconds
			: _swordStrikeAtSandbox + StrikePresentationSeconds();

		Components.Get<PlayerCombat>()?.LogMeleeAnimStart(
			"graph strike scheduled",
			$"{source} type={MeleeAttackTypes.Label( attackType )} in={remaining:0.###}s busy={GetMeleeAttackAnimBusyRemainingSeconds():0.###}s" );
	}

	/// <summary>Per frame: rest side, cocked pose, fire the strike on time, restore the rate when the clip is done.</summary>
	void TickMeleeSwing()
	{
		var body = ResolveBody();
		if ( body is null || !body.IsValid() )
			return;

		var meleeHold = ResolvePresentationHoldPose() == HoldPose.MeleeTwoHand && !_combatSequenceActive
		                && !_hitReactionPoseActive && !_ledgeMantlePoseActive;
		var now = Time.NowDouble;

		// The driving owner is still holding the button as the light strike comes due: it turns heavy, and the
		// cocked pose keeps hanging to the heavy windup (PlayerCombat decides; the host confirms the same way).
		if ( _swordCocked && _swordStrikeScheduled && !_swordStrikeStarted && now >= _swordStrikeAtSandbox
		     && ResolveCombat() is { IsValid: true } heavyCheck && heavyCheck.TryExtendOwnerSwingToHeavy( out var heavyAt )
		     && heavyAt > now )
		{
			_swordStrikeAtSandbox = heavyAt;
			_meleeAttackAnimBusyUntilSandbox = heavyAt + StrikePresentationSeconds();
		}

		if ( _swordCocked && _swordStrikeScheduled && !_swordStrikeStarted && now >= _swordStrikeAtSandbox )
		{
			_swordStrikeStarted = true;
			_swordCocked = false;
			// The strike clip ends on its own rest side; the pose under it follows so the graph lands there.
			_shownRestSide = _swordAttackType == MeleeAttackTypes.Left ? StanceLeft : StanceRight;
			_swapInProgress = false;
			if ( meleeHold )
			{
				SetSwordInterruptParam( body, false );
				SetSwordGuardParam( body, false );
				SetSwordAttackParam( body, StrikeFor( _swordAttackType ) );
				body.Set( "b_attack", true );
			}

			Components.Get<PlayerCombat>()?.LogMeleeAnimStart(
				"graph STRIKE (b_attack)",
				$"type={MeleeAttackTypes.Label( _swordAttackType )} sword_attack={StrikeFor( _swordAttackType )}" );
		}

		if ( _swordStrikeStarted && now >= _meleeAttackAnimBusyUntilSandbox )
			EndMeleeSwing( "strike clip done" );
		else if ( !_swordStrikeStarted && _swordStrikeScheduled && _swordStrikeAtSandbox == double.MaxValue
		          && now >= _meleeAttackAnimBusyUntilSandbox )
			EndMeleeSwing( "strike cue never came" );

		if ( !meleeHold )
			return;

		// A cocked pose waiting for its strike, or a raised guard, cuts a settling strike clip short.
		var guard = IsGuardStanceShown();
		SetSwordGuardParam( body, guard );
		SetSwordInterruptParam( body, !guard && _swordCocked && !_swordStrikeStarted );
		SetSwordPoseParam( body, ResolveSwordPose( now ) );
	}

	/// <summary>
	/// Cocked while a press / pending strike holds it. Otherwise the shown rest side, which follows the aim side
	/// only through the swap pose: rest → Sword_Swap_Mid (sword up in front) → other rest. A straight cross-fade
	/// between the two shoulders swept the blade through the head.
	/// </summary>
	int ResolveSwordPose( double now )
	{
		var target = ResolveRestSide();
		// Guard up: b_sword_guard shows the block pose over this selector (TickMeleeSwing), so the stance under it
		// just holds still — no shoulder swap starts behind the guard.
		if ( IsGuardStanceShown() )
		{
			_cockViaMid = false;
			_swapInProgress = false;
			return RestPoseFor( _shownRestSide );
		}

		if ( _swordCocked )
		{
			// Left shoulder <-> any right-side / overhead / stab wind-up crosses the face: brief stop in front first.
			var cockSide = RestSideFor( _swordAttackType );
			var crosses = (cockSide == StanceLeft) != (_shownRestSide == StanceLeft);
			if ( crosses && !_cockViaMid )
			{
				_cockViaMid = true;
				_cockMidUntil = now + Math.Max( 0.04f, SwordSwapMidSeconds * 0.6f );
			}

			_swapInProgress = false;
			if ( _cockViaMid && now < _cockMidUntil )
				return SwordPose.SwapMid;

			_cockViaMid = false;
			_shownRestSide = cockSide;
			return CockedPoseFor( _swordAttackType );
		}

		_cockViaMid = false;

		if ( _swordStrikeStarted )
			return RestPoseFor( _shownRestSide );

		if ( _swapInProgress )
		{
			_swapTarget = target;
			if ( now < _swapMidUntil )
				return SwordPose.SwapMid;

			_swapInProgress = false;
			_shownRestSide = _swapTarget;
		}
		else if ( target != _shownRestSide )
		{
			// Right <-> raised is one short blend on the same side of the body; anything to or from the left
			// shoulder crosses in front of the face, so it goes through the swap pose.
			if ( target != StanceLeft && _shownRestSide != StanceLeft )
			{
				_shownRestSide = target;
				return RestPoseFor( _shownRestSide );
			}

			_swapInProgress = true;
			_swapTarget = target;
			_swapMidUntil = now + Math.Max( 0.05f, SwordSwapMidSeconds );
			return SwordPose.SwapMid;
		}

		return RestPoseFor( _shownRestSide );
	}

	/// <summary>The guard is up on this peer (owner's held block or the host-confirmed block): sword rests left, shield raised.</summary>
	bool IsGuardStanceShown() =>
		ResolveCombat() is { IsValid: true, Enabled: true } combat && combat.IsGuardShown;

	/// <summary>Owner follows the live aim side and reports changes to the host; remotes read the Sync.</summary>
	byte ResolveRestSide()
	{
		var networked = GameObject.Network is { Active: true };
		var combat = ResolveCombat();
		var drivesLocally = combat is not null && combat.IsLocalCombatDriver();

		if ( drivesLocally )
		{
			var side = RestSideFor( PresentedAttackType( combat.LivePrimaryAttackType ) );
			if ( side != _ownerRestSideSent )
			{
				_ownerRestSideSent = side;
				if ( !networked || Networking.IsHost )
					NetworkedSwordRestSide = side;
				else
					RpcSubmitSwordRestSide( side );
			}

			return side;
		}

		return NetworkedSwordRestSide;
	}

	[Rpc.Host( NetFlags.Reliable )]
	void RpcSubmitSwordRestSide( byte side )
	{
		NetworkedSwordRestSide = side;
	}

	void SetSwordPoseParam( SkinnedModelRenderer body, int pose )
	{
		if ( _appliedSwordPose == pose )
			return;

		_appliedSwordPose = pose;
		body.Set( "sword_pose", pose );
	}

	void SetSwordInterruptParam( SkinnedModelRenderer body, bool interrupt )
	{
		if ( _appliedSwordInterrupt == interrupt )
			return;

		_appliedSwordInterrupt = interrupt;
		body.Set( "b_sword_interrupt", interrupt );
	}

	void SetSwordGuardParam( SkinnedModelRenderer body, bool guard )
	{
		if ( _appliedSwordGuard == guard )
			return;

		_appliedSwordGuard = guard;
		body.Set( "b_sword_guard", guard );
	}

	void SetSwordAttackParam( SkinnedModelRenderer body, int attack )
	{
		if ( _appliedSwordAttack == attack )
			return;

		_appliedSwordAttack = attack;
		body.Set( "sword_attack", attack );
	}

	/// <summary>Clear the swing state and give the body its playback rate back; the graph returns to the rest pose on its own.</summary>
	void EndMeleeSwing( string reason )
	{
		var wasActive = _swordCocked || _swordStrikeScheduled || _swordStrikeStarted;
		_swordCocked = false;
		_swordStrikeScheduled = false;
		_swordStrikeStarted = false;
		_swordStrikeAtSandbox = double.MaxValue;
		_meleeAttackAnimBusyUntilSandbox = 0;

		if ( wasActive )
			Components.Get<PlayerCombat>()?.LogMeleeAnimStopIfAny( $"end swing ({reason})" );
	}
}
